{
  "title": "老宅的秘密",
  "scene": "你站在一座古老的宅邸前，宅邸的门半开，门前的石阶上长满了青苔。宅邸的一侧是杂草丛生的庭院，另一侧是一条通往后山的小路。庭院中有一座破旧的石像，石像的基座上刻着模糊的文字。宅邸的窗户在风中轻轻作响，仿佛在诉说着什么秘密。你的目标是找到关于这座宅邸的真相。",
  "goal": "找到关于宅邸的秘密",
  "clue": "石像基座上的模糊文字",
  "choices": [
    {
      "id": "A",
      "text": "进入宅邸",
      "outcome": "你推开门，走进宅邸。宅内光线昏暗，但你发现了一本陈旧的日记。日记中记载了宅邸主人的一些奇怪行为，似乎与庭院中的石像有关。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "检查石像",
      "outcome": "你走近石像，仔细查看基座上的文字。文字虽然模糊，但你依稀辨认出是关于一个古老仪式的描述，这可能是解开宅邸秘密的关键。你决定继续调查。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "走小路",
      "outcome": "你沿着小路走向后山，但很快发现小路被茂密的树林挡住了去路。你只好原路返回，重新考虑其他策略。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
